mapper.select:
SELECT r.role_id, r.role_code, r.role_name, r.role_type, r.status, r.data_scope_type, r.is_system, r.sort_no, r.created_time, r.remark, creator.account_display as created_name FROM exp_role r LEFT JOIN exp_account creator ON r.created_by = creator.account_id
AND r.role_code LIKE CONCAT('%', #{roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{roleName}, '%')
AND r.status = #{status}
AND r.role_type = #{roleType}
ORDER BY r.sort_no ASC, r.created_time DESC

SELECT COUNT(1)
FROM exp_role
WHERE role_code = #{roleCode}

    AND role_id != #{excludeRoleId}

SELECT r.role_id, r.role_code, r.role_name, r.role_type, r.status, r.data_scope_type, r.data_scope_detail, r.is_system, r.sort_no, r.created_time, r.updated_time, r.remark, creator.account_display as created_name FROM exp_role r LEFT JOIN exp_account creator ON r.created_by = creator.account_id WHERE r.role_id IN
#{roleId}
ORDER BY r.sort_no ASC, r.created_time DESC
